    /// A blob value: the u64 handle from kaya_blob_register, consumed
    /// by the next submit; the bytes never ride the record stream.
    public readonly struct BlobHandle
    {
        public readonly ulong Handle;
        public BlobHandle(ulong handle) { Handle = handle; }
    }

    static void Pad(BinaryWriter w)
    {
        while (w.BaseStream.Position % 8 != 0)
            w.Write((byte)0);
    }

    // Values self-pad to 8: they concatenate inside record bodies.
    static void EncodeValue(BinaryWriter w, object v)
    {
        switch (v)
        {
            case bool b:
                w.Write(ValueBool); w.Write(1u); w.Write((byte)(b ? 1 : 0));
                break;
            case int i:
                w.Write(ValueI64); w.Write(8u); w.Write((long)i);
                break;
            case long l:
                w.Write(ValueI64); w.Write(8u); w.Write(l);
                break;
            case double d:
                w.Write(ValueF64); w.Write(8u); w.Write(d);
                break;
            case string s:
                byte[] utf8 = Encoding.UTF8.GetBytes(s);
                w.Write(ValueStr); w.Write((uint)utf8.Length); w.Write(utf8);
                break;
            case BlobHandle h:
                w.Write(ValueBlob); w.Write(8u); w.Write(h.Handle);
                break;
            default:
                throw new ArgumentException("kaya: value must be bool, long, double, string, or BlobHandle");
        }
        Pad(w);
    }

    // A counted value sequence — a key path or a record:
    // {u32 count, u32 reserved, count values}.
    static void EncodeValues(BinaryWriter w, object[] vals)
    {
        w.Write((uint)(vals?.Length ?? 0));
        w.Write(0u);
        foreach (object v in vals ?? Array.Empty<object>())
            EncodeValue(w, v);
    }

    // A collection schema: {u32 count, u32 reserved, count Value* tags},
    // padded to 8.
    static void EncodeVariantSchemas(BinaryWriter w, uint[][] variants)
    {
        w.Write((uint)variants.Length);
        w.Write(0u);
        foreach (uint[] schema in variants)
        {
            w.Write((uint)schema.Length);
            foreach (uint t in schema)
                w.Write(t);
        }
        Pad(w);
    }

    static byte[] Finish(MemoryStream stream, BinaryWriter w, ushort kind)
    {
        Pad(w);
        byte[] rec = stream.ToArray();
        BitConverter.GetBytes((uint)rec.Length).CopyTo(rec, 0);
        BitConverter.GetBytes(kind).CopyTo(rec, 4);
        return rec;
    }

    static BinaryWriter Begin(out MemoryStream stream)
    {
        stream = new MemoryStream();
        var w = new BinaryWriter(stream);
        w.Write(0u); w.Write((ushort)0); w.Write((ushort)0);
        return w;
    }

