    /// One representation as the decoder hands it over: the clip
    /// kind, and its values with blobs already redeemed to byte[]. Kind
    /// is a SINGLE member of the clip enum and never a mask (you offer
    /// many and you receive one); 0 with no values is the universal
    /// empty answer.
    public sealed class ClipValues
    {
        public uint Kind;
        public List<object> Values = new List<object>();
    }

    /// Decode a representation at `at`: the clip kind, then its
    /// Values block. Blobs are redeemed and RELEASED here.
    public static ClipValues ParseClip(byte[] rec, int at, out int next)
    {
        var clip = new ClipValues { Kind = BitConverter.ToUInt32(rec, at) };
        int count = (int)BitConverter.ToUInt32(rec, at + 8);
        at += 16;
        for (int i = 0; i < count; i++)
        {
            uint vtype = BitConverter.ToUInt32(rec, at);
            int vlen = (int)BitConverter.ToUInt32(rec, at + 4);
            switch (vtype)
            {
                case ValueI64: clip.Values.Add(BitConverter.ToInt64(rec, at + 8)); break;
                case ValueBlob: clip.Values.Add(Kaya.OccurrenceBlob(BitConverter.ToUInt64(rec, at + 8))); break;
                default: clip.Values.Add(Encoding.UTF8.GetString(rec, at + 8, vlen)); break;
            }
            at += 8 + ((vlen + 7) & ~7);
        }
        next = at;
        return clip;
    }

    /// Decode one occurrence record (header included). Returns false
    /// for non-click records. keys is empty for a click on a
    /// guest-created widget (id is a widget id); otherwise id is a
    /// template node id and keys is the copy's key path.
    public static bool ParseOccurrence(
        byte[] rec, out ushort kind, out ulong id, out List<object> keys, out object payload)
    {
        id = 0;
        keys = new List<object>();
        payload = null;
        kind = BitConverter.ToUInt16(rec, 4);
        if (kind != OccKindButtonClicked && kind != OccKindTextChanged && kind != OccKindToggled && kind != OccKindValueChanged && kind != OccKindCloseRequested && kind != OccKindWindowClosed && kind != OccKindAlertResult && kind != OccKindEntryPopped && kind != OccKindBackRequested && kind != OccKindSectionSelected && kind != OccKindMenuActivated && kind != OccKindMenuToggled && kind != OccKindMenuValueChanged && kind != OccKindFileDialogResult && kind != OccKindClipboardResult && kind != OccKindPasted && kind != OccKindUndone && kind != OccKindRedone && kind != OccKindSortRequested && kind != OccKindDrawRequested && kind != OccKindTick && kind != OccKindDropped && kind != OccKindDragEnded)
            return false;
        id = BitConverter.ToUInt64(rec, 8);
        if (kind == OccKindAlertResult)
        {
            // The alert's one answer: id + u32 choice (AlertChoice*).
            payload = BitConverter.ToUInt32(rec, 16);
            return true;
        }
        if (kind == OccKindFileDialogResult)
        {
            // id, a count, then three Values per file
            // (handle, name, local_path). EMPTY IS CANCEL.
            int count = (int)BitConverter.ToUInt32(rec, 16);
            int fileAt = 32; // past id, count, pad, values count, reserved
            var files = new List<PickedFile>(count);
            for (int i = 0; i < count; i++)
            {
                object?[] parts = new object?[3];
                for (int j = 0; j < 3; j++)
                {
                    uint vtype = BitConverter.ToUInt32(rec, fileAt);
                    int vlen = (int)BitConverter.ToUInt32(rec, fileAt + 4);
                    parts[j] = vtype == ValueI64
                        ? (object)BitConverter.ToInt64(rec, fileAt + 8)
                        : Encoding.UTF8.GetString(rec, fileAt + 8, vlen);
                    fileAt += 8 + ((vlen + 7) & ~7);
                }
                files.Add(new PickedFile(
                    (ulong)(long)(parts[0] ?? 0L),
                    (string)(parts[1] ?? ""),
                    (string)(parts[2] ?? "")));
            }
            payload = files;
            return true;
        }
        if (kind == OccKindClipboardResult)
        {
            payload = ParseClip(rec, 16, out int _clipEnd);
            return true;
        }
        // Surface lifecycle records carry the surface id alone
        // (derived from the record shapes).
        if (kind == OccKindCloseRequested || kind == OccKindWindowClosed || kind == OccKindEntryPopped || kind == OccKindBackRequested)
            return true;
        // Surface-pair records (window, section): the SECOND id
        // keys the handler; the first rides as the payload.
        if (kind == OccKindSectionSelected)
        {
            payload = id;
            id = BitConverter.ToUInt64(rec, 16);
            return true;
        }
        uint pathLen = BitConverter.ToUInt32(rec, 16);
        int at = 24;
        for (uint i = 0; i < pathLen; i++)
        {
            uint vtype = BitConverter.ToUInt32(rec, at);
            int vlen = BitConverter.ToInt32(rec, at + 4);
            switch (vtype)
            {
                case ValueBool: keys.Add(rec[at + 8] != 0); break;
                case ValueI64: keys.Add(BitConverter.ToInt64(rec, at + 8)); break;
                case ValueF64: keys.Add(BitConverter.ToDouble(rec, at + 8)); break;
                default: keys.Add(Encoding.UTF8.GetString(rec, at + 8, vlen)); break;
            }
            at += 8 + ((vlen + 7) & ~7);
        }
        if (kind == OccKindSortRequested)
        {
            payload = BitConverter.ToUInt32(rec, 20);
        }
        if (kind == OccKindTextChanged || kind == OccKindToggled || kind == OccKindValueChanged || kind == OccKindMenuToggled || kind == OccKindMenuValueChanged)
        {
            uint ptype = BitConverter.ToUInt32(rec, at);
            int plen = BitConverter.ToInt32(rec, at + 4);
            switch (ptype)
            {
                case ValueBool: payload = rec[at + 8] != 0; break;
                case ValueI64: payload = BitConverter.ToInt64(rec, at + 8); break;
                case ValueF64: payload = BitConverter.ToDouble(rec, at + 8); break;
                default: payload = Encoding.UTF8.GetString(rec, at + 8, plen); break;
            }
        }
        if (kind == OccKindPasted)
        {
            payload = ParseClip(rec, at, out int _pasteEnd);
        }
        if (kind == OccKindDrawRequested || kind == OccKindTick)
        {
            // The canvas asks carry a run of BARE values after the
            // key path — the assigned size, and a tick's frame time
            // — with no count in front, so they are read until the
            // record ends (docs/canvas-plan.md §3.2.1).
            int end = (int)BitConverter.ToUInt32(rec, 0);
            var tail = new List<object>();
            while (at < end)
            {
                uint ttype = BitConverter.ToUInt32(rec, at);
                int tlen = BitConverter.ToInt32(rec, at + 4);
                switch (ttype)
                {
                    case ValueBool: tail.Add(rec[at + 8] != 0); break;
                    case ValueI64: tail.Add(BitConverter.ToInt64(rec, at + 8)); break;
                    case ValueF64: tail.Add(BitConverter.ToDouble(rec, at + 8)); break;
                    default: tail.Add(Encoding.UTF8.GetString(rec, at + 8, tlen)); break;
                }
                at += 8 + ((tlen + 7) & ~7);
            }
            payload = tail;
        }
        return true;
    }
}
